INSERT INTO chamados(codigo,titulo,modulo,resumo,descricao,esperado,obtido,severidade,prioridade) VALUES
('TF-001','Erro ao cadastrar tarefa','Cadastro','O formulário retorna erro ao gravar.','Preencha os campos obrigatórios de uma nova tarefa e clique em Gravar.','A tarefa deve ser salva e aparecer na listagem.','O sistema retorna ao formulário sem cadastrar.','Alta','Alta'),
('TF-002','Filtro apresenta resultado incorreto','Listagem','O filtro não respeita o status selecionado.','Selecione Em andamento e clique em Filtrar. Compare os status exibidos.','Somente tarefas do status escolhido.','A listagem apresenta tarefas pendentes mesmo selecionando outro status.','Média','Média'),
('TF-003','Indicador de prioridade incorreto','Dashboard','A quantidade de tarefas prioritárias não corresponde aos registros.','Compare tarefas de prioridade Alta na listagem com o indicador do Dashboard.','Contar somente tarefas Alta.','O indicador inclui também tarefas Média.','Média','Média'),
('TF-004','Edição não atualiza o status','Edição','Após editar, o status permanece com valor anterior.','Edite uma tarefa, altere o status e grave. Reabra a tarefa.','Todos os campos alterados devem ser persistidos.','O status não é atualizado.','Alta','Alta'),
('TF-005','Contagem de concluídas incorreta','Dashboard','O Dashboard não contabiliza corretamente tarefas concluídas.','Altere uma tarefa para Concluída e confira o indicador.','A quantidade deve refletir a alteração.','A contagem permanece incorreta.','Alta','Alta'),
('TF-006','Exclusão sem confirmação','Exclusão','A tarefa é removida imediatamente ao clicar em Excluir.','Na listagem, clique em Excluir e observe se há confirmação.','Solicitar confirmação antes de excluir.','A tarefa é excluída diretamente.','Baixa','Baixa');
